def countRegions(cells):
    R, C = len(cells), len(cells[0])
    H, W = 3 * R, 3 * C
    blocked = [[False] * W for _ in range(H)]
    for r in range(R):
        for c in range(C):
            if cells[r][c] == 1:
                for k in range(3):
                    blocked[3 * r + k][3 * c + 2 - k] = True
            elif cells[r][c] == 2:
                for k in range(3):
                    blocked[3 * r + k][3 * c + k] = True
    regions = 0
    for i in range(H):
        for j in range(W):
            if not blocked[i][j]:
                regions += 1
                blocked[i][j] = True
                stack = [(i, j)]
                while stack:
                    y, x = stack.pop()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and not blocked[ny][nx]:
                            blocked[ny][nx] = True
                            stack.append((ny, nx))
    return regions
